/* Project-authored no-op helper and old-map carrier; GPL-2.0-only.
 * The L-format sector layout follows the existing launch_disc.c transport.
 * No Arculator implementation or generated bytes are changed. */
#include "rpc_launch_helper.h"
#include <string.h>
static uint32_t get(const uint8_t *p) { return p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24; }
static void put(uint8_t *p,uint32_t n) { for(unsigned i=0;i<4;++i)p[i]=(uint8_t)(n>>(i*8)); }
static void u24(uint8_t *p,unsigned n) { for(unsigned i=0;i<3;++i)p[i]=(uint8_t)(n>>(i*8)); }
bool arc_riscpc_helper_descriptor(const uint8_t *p,size_t n,uint32_t *entry)
{
    if(!p || n<68 || n>ARC_RPC_HELPER_MAX || (n&3) || memcmp(p,"ARCRHLP1",8) ||
       get(p+8)!=1 || get(p+12)!=64 || get(p+16)!=n || get(p+20)!=1 || get(p+24)!=1 ||
       get(p+32)!=1 || get(p+36)!=1 || get(p+40)!=1 || get(p+52) || get(p+56) || get(p+60))return false;
    uint32_t e=get(p+28),at=get(p+44),bytes=get(p+48);
    if(e<64 || e>n-4 || (e&3) || at<e+4 || at>n || (at&3) || bytes>n-at)return false;
    if(entry)*entry=e;
    return true;
}
static uint8_t checksum(const uint8_t *p)
{
    unsigned c=255;
    for(unsigned i=255;i-->0;){if(c>255)c=(c+1)&255;c+=p[i];}
    return (uint8_t)c;
}
static size_t physical(unsigned sector)
{ unsigned track=sector/16;return ((track%80)*2+track/80)*4096+(sector%16)*256; }
bool arc_riscpc_helper_build(uint8_t *out,size_t capacity)
{
    if(!out || capacity<ARC_RPC_HELPER_SIZE)return false;
    memset(out,0,ARC_RPC_HELPER_SIZE);
    /* All carrier sectors beyond 7 are free. Root is logical sector 2. */
    u24(out,8);u24(out+252,2560);u24(out+256,2552);
    memcpy(out+247,"Acri\r",5);memcpy(out+502,"rDod\r",5);
    out[507]=0x44;out[508]=0x41;out[510]=3;
    out[255]=checksum(out);out[511]=checksum(out+256);
    uint8_t *root=out+physical(2);root[0]=1;memcpy(root+1,"Hugo",4);
    uint8_t *row=root+5;memset(row,'\r',10);memcpy(row,"ArcHelper",9);
    row[0]|=0x80; /* Owner read only; backing additionally forbids all writes. */
    put(row+10,0xfff00000);put(row+18,144);u24(row+22,7);
    uint8_t *tail=root+1227;memset(tail+1,'\r',10);tail[1]='$';u24(tail+11,2);
    memcpy(tail+14,"ArcDroid helper",14);tail[47]=1;memcpy(tail+48,"Hugo",4);
    uint8_t *p=out+physical(7);memcpy(p,"ARCRHLP1",8);
    const uint32_t fields[]={1,64,144,1,1,64,1,1,1,136,8,0,0,0};
    for(unsigned i=0;i<14;++i)put(p+8+i*4,fields[i]);
    /* ARM610-compatible leaf: reject a non-eight-byte plan before any read,
     * then validate plan version/action. All paths write status and return. */
    const uint32_t code[]={0xe5903030,0xe3530008,0x1a000008,
        0xe590302c,0xe0803003,0xe5930000,0xe3500001,0x05930004,
        0x03500000,0x03a00002,0x13a00003,0xea000000,
        0xe3a00003,0xe582000c,0xe10f3000,0xe3130010,0x01b0f00e,0x11a0f00e};
    for(unsigned i=0;i<18;++i)put(p+64+i*4,code[i]);
    put(p+136,1);put(p+140,0);
    return true;
}
